package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

// TerraformProviderResource handles CRUD for a custom Terraform provider
// that manages MongoDB-backed configuration documents
type TerraformProviderResource struct {
	client     *mongo.Client
	collection *mongo.Collection
}

type ResourceReadRequest struct {
	ID        string                 `json:"id"`
	Namespace string                 `json:"namespace"`
	Filter    map[string]interface{} `json:"filter"`
}

type ResourceReadResponse struct {
	Data   map[string]interface{} `json:"data,omitempty"`
	Error  string                 `json:"error,omitempty"`
	Status int                    `json:"status"`
}

func NewProvider(mongoURI, dbName, collName string) (*TerraformProviderResource, error) {
	client, err := mongo.Connect(context.Background(), options.Client().ApplyURI(mongoURI))
	if err != nil {
		return nil, err
	}
	collection := client.Database(dbName).Collection(collName)
	return &TerraformProviderResource{client: client, collection: collection}, nil
}

// ReadResource implements the provider's Read function
// Called during terraform plan/apply to refresh state
func (p *TerraformProviderResource) ReadResource(w http.ResponseWriter, r *http.Request) {
	var req ResourceReadRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	// Build the query filter from the request
	// The filter is passed directly from the Terraform configuration
	queryFilter := bson.M{}

	if req.ID != "" {
		queryFilter["_id"] = req.ID
	}

	if req.Namespace != "" {
		queryFilter["namespace"] = req.Namespace
	}

	// Merge additional filter criteria from the Terraform data source block
	// This allows flexible querying: data "custom_config" "example" { filter = {...} }
	for key, value := range req.Filter {
		queryFilter[key] = value
	}

	// Execute the query against MongoDB
	var result bson.M
	err := p.collection.FindOne(context.Background(), queryFilter).Decode(&result)
	if err != nil {
		if err == mongo.ErrNoDocuments {
			json.NewEncoder(w).Encode(ResourceReadResponse{
				Status: 404,
				Error:  "resource not found",
			})
			return
		}
		log.Printf("MongoDB query error: %v", err)
		json.NewEncoder(w).Encode(ResourceReadResponse{
			Status: 500,
			Error:  "internal error",
		})
		return
	}

	// Convert result for Terraform state
	data := make(map[string]interface{})
	for k, v := range result {
		data[k] = v
	}

	json.NewEncoder(w).Encode(ResourceReadResponse{
		Data:   data,
		Status: 200,
	})
}

// DeleteResource handles terraform destroy
func (p *TerraformProviderResource) DeleteResource(w http.ResponseWriter, r *http.Request) {
	var req ResourceReadRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	deleteFilter := bson.M{}
	if req.ID != "" {
		deleteFilter["_id"] = req.ID
	}
	// Allow bulk delete by namespace via filter
	for key, value := range req.Filter {
		deleteFilter[key] = value
	}

	result, err := p.collection.DeleteMany(context.Background(), deleteFilter)
	if err != nil {
		json.NewEncoder(w).Encode(map[string]interface{}{"error": err.Error()})
		return
	}

	json.NewEncoder(w).Encode(map[string]interface{}{
		"deleted_count": result.DeletedCount,
		"status":        200,
	})
}

func main() {
	provider, err := NewProvider("mongodb://localhost:27017", "terraform_state", "resources")
	if err != nil {
		log.Fatal(err)
	}

	http.HandleFunc("/read", provider.ReadResource)
	http.HandleFunc("/delete", provider.DeleteResource)

	fmt.Println("Terraform provider backend listening on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
